/* Extracted verbatim from glossary.html so the site can carry a real
   script-src. Behaviour is unchanged: the tag sits where the inline
   block sat, with no defer or async, so execution order is identical.
   Edit here, not in the HTML. */

(function () {
  applyPartner(); mountChrome();
  const $ = id => document.getElementById(id);

  let q = "", cat = "all";

  /* The terms are in the markup, generated by scripts/build-glossary.mjs.
     They used to be rendered here from JKG at load, which cost 0.40 of
     cumulative layout shift on every visit and left non-JS crawlers
     looking at an empty page. This script now only filters what is
     already there. */
  const terms  = [...document.querySelectorAll(".g-term")];
  const groups = [...document.querySelectorAll(".g-group")];
  const HAY = new Map(terms.map(el => [el, el.textContent.toLowerCase()]));

  $("g-total").textContent = terms.length;

  /* ---------- category filter ----------
     The chips are in the markup too; this only binds them. */
  $("g-cats").querySelectorAll(".seg").forEach(b => b.addEventListener("click", () => {
    setCat(b.dataset.c);
    render();
  }));
  function setCat(next) {
    cat = next;
    $("g-cats").querySelectorAll(".seg").forEach(x => x.setAttribute("aria-pressed", String(x.dataset.c === cat)));
  }

  /* ---------- search ---------- */
  $("g-q").addEventListener("input", () => { q = $("g-q").value; render(); });

  /* ---------- render ---------- */
  function render() {
    const s = q.trim().toLowerCase();
    let shown = 0;

    terms.forEach(el => {
      const catOk = cat === "all" || el.dataset.cat === cat;
      const qOk = !s || HAY.get(el).includes(s);
      const on = catOk && qOk;
      el.hidden = !on;
      if (on) shown++;
    });

    // a group with nothing left in it is a heading over empty space
    groups.forEach(g => {
      const live = [...g.querySelectorAll(".g-term")].filter(t => !t.hidden).length;
      g.hidden = live === 0;
      const n = g.querySelector(".g-n");
      if (n) n.textContent = live;
    });

    // Searching mutes the category headings — when you are hunting a word
    // they are noise. Browsing keeps them, because then the grouping is
    // the point. Done with a class rather than by reordering nodes, which
    // would reintroduce the layout thrash this rewrite removed.
    $("g-body").classList.toggle("is-searching", !!s);

    $("g-count").textContent = shown === terms.length
      ? `${shown} terms`
      : `${shown} of ${terms.length} terms`;
    $("g-empty").hidden = shown > 0;
    renderLetters();
  }

  /* A–Z rail. Letters with no visible term are shown but inert, so the
     rail keeps a stable width instead of reflowing on every keystroke. */
  function renderLetters() {
    const have = {};
    terms.forEach(el => {
      if (el.hidden) return;
      const L = el.querySelector("h3").textContent.trim()[0].toUpperCase();
      if (!have[L]) have[L] = el.id;
    });
    $("g-letters").innerHTML = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("").map(L =>
      have[L] ? `<a href="#${have[L]}">${L}</a>` : `<span aria-hidden="true">${L}</span>`).join("");
  }

  /* A "see also" chip may point at a term the current filter hides, so
     clicking it clears the filter first — otherwise the jump lands on
     nothing and reads as a broken link. */
  $("g-body").addEventListener("click", e => {
    const a = e.target.closest("[data-jump]");
    if (!a) return;
    const target = document.getElementById(a.getAttribute("href").slice(1));
    if (!target) return;
    if (target.hidden) {
      setCat("all");
      q = ""; $("g-q").value = "";
      render();
    }
    requestAnimationFrame(() => target.scrollIntoView({ block: "center", behavior: "smooth" }));
  });

  /* deep link: /glossary.html#t-dscr, or ?q=dscr from another page */
  const urlQ = new URLSearchParams(location.search).get("q");
  if (urlQ) { q = urlQ; $("g-q").value = urlQ; }
  render();
  if (location.hash) {
    const el = document.querySelector(location.hash);
    if (el) requestAnimationFrame(() => el.scrollIntoView({ block: "center" }));
  }

  $("cta-mail").href = toolMailto("Glossary", "Aviation venture enquiry",
    "I came through the glossary and would like to discuss a venture.\n\n");
})();
